<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {service} from '@/services/service'
import {uniqueWords,mergeLexicon,lexiconSignature,type LexiconEntry} from '@/domain/lexicon'
const props=defineProps<{modelValue:boolean;stopWords:string[];newWords:string[]}>()
const emit=defineEmits<{'update:modelValue':[boolean];apply:[LexiconEntry[]]}>()
const rows=ref<LexiconEntry[]>([]),selected=ref<string[]>([]),original=ref<LexiconEntry[]>([]),query=ref(''),kind=ref<''|'stop'|'user'>(''),page=ref(1),busy=ref(false),error=ref(''),input=ref(''),newKind=ref<'stop'|'user'>('stop')
const filtered=computed(()=>rows.value.filter(r=>(!kind.value||r.kind===kind.value)&&(!query.value||r.word.includes(query.value.trim())))),paged=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20)),dirty=computed(()=>lexiconSignature(rows.value)!==lexiconSignature(original.value))
const checked=computed(()=>paged.value.length>0&&paged.value.every(r=>selected.value.includes(r.word)))
watch([query,kind],()=>page.value=1)
watch(()=>props.modelValue,async open=>{if(!open)return;busy.value=true;error.value='';try{rows.value=await service.loadLexicon();original.value=JSON.parse(JSON.stringify(rows.value));selected.value=rows.value.filter(r=>(r.kind==='stop'?props.stopWords:props.newWords).includes(r.word)).map(r=>r.word);page.value=1}catch(e){error.value=(e as Error).message}finally{busy.value=false}})
function toggle(word:string,yes:boolean){selected.value=yes?[...new Set([...selected.value,word])]:selected.value.filter(w=>w!==word)}
function togglePage(yes:boolean){for(const r of paged.value)toggle(r.word,yes)}
async function add(text=input.value){const words=uniqueWords(text);if(!words.length)return;const conflicts=words.filter(w=>rows.value.some(r=>r.word===w&&r.kind!==newKind.value));let overwrite=false;if(conflicts.length){try{await ElMessageBox.confirm(`${conflicts.length} 个词已属于另一类型。是否改为${newKind.value==='stop'?'停用词':'新词'}？`,'处理词条冲突',{confirmButtonText:'更改类型',cancelButtonText:'忽略冲突',distinguishCancelAndClose:true});overwrite=true}catch(e){if(e==='close')return}}rows.value=mergeLexicon(rows.value,words,newKind.value,overwrite);input.value=''}
async function edit(row:LexiconEntry){try{const {value}=await ElMessageBox.prompt('修改词条内容','编辑词条',{inputValue:row.word,inputValidator:v=>!!v.trim()||'请填写词条'});const word=value.trim();if(rows.value.some(r=>r!==row&&r.word===word)){ElMessage.warning('词条已存在');return}selected.value=selected.value.map(w=>w===row.word?word:w);row.word=word}catch{}}
async function save(){busy.value=true;try{await service.saveLexicon(rows.value,original.value);original.value=JSON.parse(JSON.stringify(rows.value));ElMessage.success('词库已保存')}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function importFile(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('词表文件不能超过 2 MB');await add(await file.text())}catch(e){ElMessage.error((e as Error).message)}finally{(e.target as HTMLInputElement).value=''}}
watch(()=>filtered.value.length,()=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/20)))})
function apply(){emit('apply',rows.value.filter(r=>selected.value.includes(r.word)));emit('update:modelValue',false)}
</script>
<template><el-dialog :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" title="我的词库" width="960px" append-to-body :close-on-click-modal="false"><div v-loading="busy"><p class="help">维护常用词，勾选后添加到本次词表。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-else><div class="toolbar"><el-input v-model="query" placeholder="查找词条" style="width:230px"/><el-select v-model="kind" style="width:130px"><el-option label="全部类型" value=""/><el-option label="停用词" value="stop"/><el-option label="新词" value="user"/></el-select><span class="muted">已选 {{selected.length}} 个</span><el-button link type="primary" @click="filtered.forEach(r=>toggle(r.word,true))">选择全部页</el-button><el-button link @click="filtered.forEach(r=>toggle(r.word,false))">取消本范围</el-button></div><el-table :data="paged" height="340"><el-table-column width="76"><template #header><el-checkbox :model-value="checked" @change="togglePage(Boolean($event))">本页</el-checkbox></template><template #default="{row}"><el-checkbox :model-value="selected.includes(row.word)" :aria-label="'选用 '+row.word" @change="toggle(row.word,Boolean($event))"/></template></el-table-column><el-table-column label="类型" width="110"><template #default="{row}">{{row.kind==='stop'?'停用词':'新词'}}</template></el-table-column><el-table-column prop="word" label="词条"/><el-table-column label="操作" width="150"><template #default="{row}"><el-button text @click="edit(row)">编辑</el-button><el-button text type="danger" @click="rows=rows.filter(r=>r.word!==row.word);selected=selected.filter(w=>w!==row.word)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="filtered.length" :page-size="20" layout="total,prev,pager,next"/><div class="toolbar add-words"><el-select v-model="newKind" style="width:130px"><el-option label="停用词" value="stop"/><el-option label="新词" value="user"/></el-select><el-input v-model="input" placeholder="输入词条，多个可用逗号分隔" aria-label="新增词条" style="flex:1" @keyup.enter="add()"/><el-button @click="add()">添加</el-button><label class="import-words">导入词表<input type="file" accept=".txt,.csv" @change="importFile"/></label></div></template></div><template #footer><span v-if="dirty" class="muted" style="float:left">词库有未保存的修改</span><el-button @click="emit('update:modelValue',false)">关闭</el-button><el-button :disabled="!dirty||!!error" :loading="busy" @click="save">保存词库</el-button><el-button type="primary" :disabled="!!error||busy" @click="apply">添加到本次词表</el-button></template></el-dialog></template>
<style scoped>.add-words{margin-top:16px}.import-words{position:relative;padding:5px 12px;border:1px solid #dce3ed;border-radius:6px;font-size:14px}.import-words input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.el-pagination{margin-top:12px;justify-content:flex-end}</style>
